<article class="server-card"><div class="card-top"><span class="tag">{{ $server->game === 'cs16' ? 'CS 1.6' : 'CS:GO' }}</span><span class="status {{ $server->is_online ? 'on' : 'off' }}"><i></i>{{ $server->is_online ? 'ONLINE' : 'OFFLINE' }}</span></div><div class="map"><small>CURRENT MAP</small><b>{{ strtoupper($server->current_map ?? 'UNKNOWN') }}</b><span>{{ $server->category->name }}</span></div><div class="card-body"><h3><a href="{{ route('servers.show',$server) }}">{{ $server->name }}</a></h3><button class="copy" data-copy="{{ $server->address() }}">{{ $server->address() }} ⧉</button><div class="bar"><i style="width:{{ $server->max_players ? min(100,round($server->current_players/$server->max_players*100)) : 0 }}%"></i></div><div class="stats"><span><small>ИГРАЧИ</small><b>{{ $server->current_players }}/{{ $server->max_players }}</b></span><span><small>ПИНГ</small><b>{{ $server->last_ping_ms ?? '—' }} ms</b></span><a href="{{ route('servers.show',$server) }}">Детайли →</a></div></div></article>
